//! Source-only diagnostic preparation: delegates every helper invocation unchanged.
use js_runtime::{Runtime,Value,EnvId,JsResult,JsError,ObjectKind,PropertyKey,PropertyKind};
use std::{cell::RefCell,collections::BTreeMap};
thread_local!{static COUNTS:RefCell<BTreeMap<usize,(u64,u64)>>=RefCell::new(BTreeMap::new());}
const NAMES:[&str;11]=["edpAdd","edpSub","edpMult","edpLengthSQ","edpDistanceSQ","edpNormalize","edpCompMult","edpAngle","edpCross","edpMid","edpDot"];
fn finite_vec2(rt:&Runtime,value:Value)->bool{let Value::Object(id)=value else{return false};let o=&rt.objects[id.0];matches!(o.kind,ObjectKind::Array{length:2,..})&&(0..2).all(|i|matches!(o.own(PropertyKey(js_runtime::StringId(i))).map(|d|d.kind),Some(PropertyKind::Data{value:Value::Number(n),..})if n.is_finite()))}
fn call(rt:&mut Runtime,this:Value,args:&[Value],env:EnvId)->JsResult<Value>{let Value::Number(index)=rt.lookup(env,"vectorDiagnosticIndex")?else{return Err(JsError::Unsupported("vector counter index".into()))};let index=index as usize;let eligible=args.first().copied().is_some_and(|v|finite_vec2(rt,v))&&match index{2=>matches!(args.get(1),Some(Value::Number(n))if n.is_finite()),3|5=>true,_=>args.get(1).copied().is_some_and(|v|finite_vec2(rt,v))};COUNTS.with(|c|{let mut c=c.borrow_mut();let row=c.entry(index).or_default();row.0+=1;row.1+=u64::from(eligible);});let original=rt.lookup(env,"vectorDiagnosticOriginal")?;rt.call_value(original,this,args)}
pub fn install(rt:&mut Runtime,env:EnvId)->JsResult<()>{let ed=rt.lookup(env,"ed")?;let key=rt.string("toString");let to_string=rt.get(Value::Object(rt.function_prototype),key)?;for(index,name)in NAMES.into_iter().enumerate(){let key=rt.string(name);let original=rt.get(ed,key)?;if !matches!(original,Value::Function(_)){continue}let source=rt.call_value(to_string,original,&[])?;let Value::String(id)=source else{panic!()};eprintln!("VECTOR_SOURCE:{}:{}",name,rt.string_text(id));let units=rt.string_units(id).to_vec();let capture=rt.child_env(env);rt.declare(capture,"vectorDiagnosticOriginal",original)?;rt.declare(capture,"vectorDiagnosticIndex",Value::Number(index as f64))?;let arity=if index==3||index==5{1}else{2};let wrapper=rt.make_closure_with_flags(call,capture,arity,name,true,None);rt.set_function_source(wrapper,&units)?;rt.set(ed,key,wrapper,true)?;}Ok(())}
pub fn finish(){COUNTS.with(|c|for(&i,&(calls,finite_dense2))in c.borrow().iter(){eprintln!("VECTOR_CALLS:{{\"name\":\"{}\",\"calls\":{},\"finiteDense2InputCalls\":{}}}",NAMES[i],calls,finite_dense2)});}
